<template>
  <F7Messagebar :placeholder="placeholder" :value="text" @input="onInput">
    <template #inner-end>
      <F7Link
        :class="canSend ? 'opacity-100' : 'pointer-events-none opacity-40'"
        icon-only
        @click="submit"
      >
        <span
          class="flex h-9 w-9 items-center justify-center rounded-full bg-[color:var(--f7-theme-color)] text-white"
        >
          <ILucideArrowUp class="h-[18px] w-[18px]" />
        </span>
      </F7Link>
    </template>
  </F7Messagebar>
</template>

<script setup lang="ts">
import { computed, ref } from "vue";

const props = defineProps<{ sending?: boolean; placeholder?: string }>();
const emit = defineEmits<{ send: [string]; typing: [] }>();

const text = ref("");
const placeholder = computed(() => props.placeholder ?? "Message");
const canSend = computed(() => text.value.trim().length > 0 && !props.sending);

function onInput(event: Event) {
  text.value = (event.target as HTMLInputElement | HTMLTextAreaElement).value;
  if (text.value.trim()) emit("typing");
}

function submit() {
  const value = text.value.trim();
  if (!value || props.sending) return;
  emit("send", value);
  text.value = "";
}
</script>
