import type { Router } from "framework7/types";

const messengerRoutes: Router.RouteParameters[] = [
  {
    name: "messenger",
    path: "/messenger",
    async({ resolve }) {
      import("@/modules/messenger/views/MessengerView.vue").then((vc) => {
        resolve({ component: vc.default });
      });
    },
  },
  {
    name: "messenger-thread",
    path: "/messenger/:channelId",
    async({ resolve }) {
      import("@/modules/messenger/views/MessengerThreadView.vue").then((vc) => {
        resolve({ component: vc.default });
      });
    },
  },
];

export default messengerRoutes;
