import { format, isThisYear, isToday, isYesterday } from "date-fns";
import type { ThreadMessage } from "@aybsig/messenger";
import { toDate } from "./messenger.format";

export type ThreadRenderItem =
  | { kind: "title"; key: string; label: string }
  | {
      kind: "message";
      key: string;
      message: ThreadMessage;
      first: boolean;
      last: boolean;
      tail: boolean;
    };

export function messageBodyToText(body: string): string {
  if (!body) return "";
  return body
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|li)>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function dayKey(value: string | null): string {
  if (!value) return "unknown";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "unknown";
  return format(date, "yyyy-MM-dd");
}

export function formatMessageTime(value: string | null): string {
  if (!value) return "";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "";
  return format(date, "HH:mm");
}

export function formatDayTitle(value: string | null): string {
  if (!value) return "";
  const date = toDate(value);
  if (Number.isNaN(date.getTime())) return "";
  if (isToday(date)) return "Today";
  if (isYesterday(date)) return "Yesterday";
  if (isThisYear(date)) return format(date, "EEEE, d MMM");
  return format(date, "d MMM yyyy");
}

function sameGroup(a: ThreadMessage, b: ThreadMessage, key: string): boolean {
  return a.isMine === b.isMine && a.authorId === b.authorId && dayKey(a.date) === key;
}

export function buildThreadItems(messages: readonly ThreadMessage[]): ThreadRenderItem[] {
  const items: ThreadRenderItem[] = [];
  let previousDay: string | null = null;

  messages.forEach((message, index) => {
    const key = dayKey(message.date);
    if (key !== previousDay) {
      items.push({ kind: "title", key: `title-${key}-${message.id}`, label: formatDayTitle(message.date) });
      previousDay = key;
    }

    const prev = messages[index - 1];
    const next = messages[index + 1];
    const first = !prev || !sameGroup(prev, message, key);
    const last = !next || !sameGroup(next, message, key);

    items.push({
      kind: "message",
      key: message.tempId ?? `msg-${message.id}`,
      message,
      first,
      last,
      tail: last,
    });
  });

  return items;
}
