<template>
  <F7Sheet
    :opened="opened"
    backdrop
    class="messenger-new-chat-sheet height-auto !rounded-t-2xl"
    @sheet:closed="emit('update:opened', false)"
  >
    <div class="px-4 pb-[max(16px,env(safe-area-inset-bottom))] pt-3">
      <div class="mx-auto mb-3 h-1.5 w-10 rounded-full bg-[#cdd8ec]"></div>
      <h2 class="mb-2 text-[17px] font-[820] text-[#090e24]">New conversation</h2>

      <F7List class="!my-0">
        <F7ListInput
          type="text"
          :value="query"
          clear-button
          placeholder="Search people"
          @input="onQuery"
        />
      </F7List>

      <div class="max-h-[52vh] overflow-y-auto pt-1">
        <p v-if="searching" class="py-6 text-center text-[13px] text-[#657096]">Searching…</p>
        <p v-else-if="!results.length" class="py-6 text-center text-[13px] text-[#657096]">
          No people found.
        </p>
        <ul v-else class="space-y-0.5">
          <li v-for="person in results" :key="person.id">
            <button
              class="flex w-full items-center gap-3 rounded-2xl px-2 py-2 text-left active:bg-[#eef3fc]"
              :disabled="starting"
              @click="choose(person.id)"
            >
              <MessengerChannelAvatar
                compact
                :name="person.name"
                :image-url="person.imageUrl"
                channel-type="chat"
              />
              <span class="flex-1 text-[14px] font-[620] text-[#090e24]">{{ person.name }}</span>
              <span v-if="person.online" class="h-2.5 w-2.5 rounded-full bg-[#2bd279]"></span>
            </button>
          </li>
        </ul>
      </div>
    </div>
  </F7Sheet>
</template>

<script setup lang="ts">
import { watch } from "vue";
import { useMessengerNewChat } from "@aybsig/messenger/vue";
import MessengerChannelAvatar from "./MessengerChannelAvatar.vue";

const props = defineProps<{ opened: boolean }>();
const emit = defineEmits<{ "update:opened": [boolean]; started: [number] }>();

const { query, results, searching, starting, loadInitial, start } = useMessengerNewChat();

watch(
  () => props.opened,
  (open) => {
    if (open) void loadInitial();
  },
);

function onQuery(event: Event) {
  query.value = (event.target as HTMLInputElement).value;
}

async function choose(partnerId: number) {
  const channelId = await start(partnerId);
  emit("update:opened", false);
  if (channelId != null) emit("started", channelId);
}
</script>
